"""Read-only bounded DC tradeoff; does not change circuits or acceptance budgets."""
from pathlib import Path
import hashlib,json,math
H=Path(__file__).resolve().parent;source=H.parent/'dock-safety/power-budget.json';d=json.loads(source.read_text());u=d['UV_normal_design'];p=u['LED_power_total_W']+u['bleeder_and_divider_power_total_W'];eta=.7;iq=u['driver_Iq_total_mA']/1000;limit=d['UV_limiter_min_mA']/1000;rs=d['UV_path_resistance']['common_switch_Rmax_ohm'];rb=d['UV_path_resistance']['each_branch_supply_plus_return_max_ohm'];other=(d['device_qualified_allocation_mA']+d['dock_UI_overhead_allocation_mA']+d['contact_loops']['qualified_total_max_mA'])/1000
